def run(w):
    cols=[np.ones_like(t),x,x*x,x**3,v,v*v,x*v,1/v,np.cos(w*t),np.sin(w*t),np.cos(2*w*t),np.sin(2*w*t),np.cos(3*w*t),np.sin(3*w*t)]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    return np.mean((X@c-dv_dt)**2)/np.var(dv_dt), c
